const $=(s,c=document)=>c.querySelector(s);const $$=(s,c=document)=>[...c.querySelectorAll(s)];
const months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const days=['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];
const now=new Date();$('#current-date').textContent=`${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]}`;
function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));scrollTo({top:0,behavior:'smooth'})}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('[data-action="profile"]').onclick=()=>showView('profile');
const modal=$('#modal'),content=$('#modal-content');$('.modal-close').onclick=()=>modal.close();
const flowCopy={
 natal:{k:'НАТАЛЬНАЯ КАРТА',n:'Солнце в Водолее',v:'☉',p:'Независимое мышление сочетается у тебя с сильной потребностью находить смысл и создавать системы. Твоя карта подчёркивает ценность свободы, но близкие отношения требуют честно проговаривать границы.',tags:['Солнце · Водолей','Луна · Весы','Асцендент · Скорпион']},
 matrix:{k:'МАТРИЦА СУДЬБЫ',n:'Твой центр — 10 аркан',v:'10',p:'Твоя ключевая тема — видеть возможности в переменах и превращать хаос в направление. Сильная сторона — адаптивность; задача — не отдавать решения на волю обстоятельств.',tags:['Характер · 3','Предназначение · 11','Ресурс · 19']},
 couple:{k:'СОВМЕСТИМОСТЬ',n:'Энергия пары — 6 аркан',v:'6',p:'Центральная тема этой связи — осознанный выбор друг друга. Притяжение усиливается общими решениями, а напряжение возникает, когда третьи лица становятся важнее договорённостей пары.',tags:['Чувства · 14','Быт · 8','Деньги · 17']}
};
function openResult(o){content.innerHTML=`<div class="result-copy"><div class="eyebrow">${o.k}</div><div class="result-wheel"><span>${o.v}</span></div><h2>${o.n}</h2><div class="result-tags">${o.tags.map(x=>`<span>${x}</span>`).join('')}</div><p>${o.p}</p><button class="primary-btn" onclick="document.querySelector('#modal').close()">Понятно</button></div>`;modal.showModal()}
const apiBase=(window.ORBITA_API_URL||'').replace(/\/$/,'');
const planetNames={Sun:'Солнце',Moon:'Луна',Mercury:'Меркурий',Venus:'Венера',Mars:'Марс',Jupiter:'Юпитер',Saturn:'Сатурн',Uranus:'Уран',Neptune:'Нептун',Pluto:'Плутон','True Node':'Северный узел'};
const signNames={Aries:'Овен',Taurus:'Телец',Gemini:'Близнецы',Cancer:'Рак',Leo:'Лев',Virgo:'Дева',Libra:'Весы',Scorpio:'Скорпион',Sagittarius:'Стрелец',Capricorn:'Козерог',Aquarius:'Водолей',Pisces:'Рыбы'};
function zodiac(longitude){const signs=['Овен','Телец','Близнецы','Рак','Лев','Дева','Весы','Скорпион','Стрелец','Козерог','Водолей','Рыбы'];return `${(longitude%30).toFixed(1)}° ${signs[Math.floor((longitude%360)/30)]}`}
function natalForm(){content.innerHTML=`<form class="natal-form" id="natal-form"><div class="eyebrow">НАТАЛЬНАЯ КАРТА</div><h2>Данные рождения</h2><p>Положения планет и дома рассчитает Swiss Ephemeris. Интерпретация не меняет исходные числа.</p><label>Дата рождения<input required name="birthdate" type="date" value="1990-01-01"></label><label>Точное время<input required name="birthtime" type="time" value="12:00"></label><label>Место рождения<input required id="place-query" autocomplete="off" placeholder="Начните вводить город"></label><div class="place-results" id="place-results"></div><input name="latitude" type="hidden"><input name="longitude" type="hidden"><input name="timezone" type="hidden"><div class="form-state" id="natal-state"></div><button class="primary-btn" type="submit">Рассчитать карту</button></form>`;modal.showModal();bindNatalForm()}
function bindNatalForm(){const form=$('#natal-form'),query=$('#place-query'),results=$('#place-results'),state=$('#natal-state');let timer;
 query.oninput=()=>{clearTimeout(timer);form.latitude.value='';form.longitude.value='';form.timezone.value='';results.replaceChildren();const value=query.value.trim();if(value.length<2)return;timer=setTimeout(async()=>{if(!apiBase){state.textContent='Расчётный сервер готовится к подключению';return}state.textContent='Ищем место…';try{const response=await fetch(`${apiBase}/v1/places/search?q=${encodeURIComponent(value)}`);if(!response.ok)throw new Error();const places=await response.json();state.textContent=places.length?'Выберите место из списка':'Ничего не найдено';results.replaceChildren(...places.map(place=>{const button=document.createElement('button');button.type='button';button.textContent=place.label;button.onclick=()=>{query.value=place.label;form.latitude.value=place.latitude;form.longitude.value=place.longitude;form.timezone.value=place.timezone;results.replaceChildren();state.textContent=`Часовой пояс: ${place.timezone}`};return button}))}catch{state.textContent='Не удалось выполнить поиск. Попробуйте ещё раз.'}},350)};
 form.onsubmit=async event=>{event.preventDefault();if(!apiBase){state.textContent='API пока не опубликован. Код расчёта уже доступен в GitHub.';return}if(!form.timezone.value){state.textContent='Сначала выберите место из списка';return}state.textContent='Вычисляем положения планет…';const data=new FormData(form);try{const response=await fetch(`${apiBase}/v1/natal-chart`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({birth_datetime:`${data.get('birthdate')}T${data.get('birthtime')}:00`,timezone:data.get('timezone'),latitude:Number(data.get('latitude')),longitude:Number(data.get('longitude')),house_system:'P'})});const payload=await response.json();if(!response.ok)throw new Error(payload.detail||'Ошибка расчёта');renderNatal(payload)}catch(error){state.textContent=error.message||'Не удалось рассчитать карту'}}}
function renderNatal(chart){const rows=Object.entries(chart.planets).map(([name,p])=>`<li><strong>${planetNames[name]||name}</strong><span>${p.degree_in_sign.toFixed(1)}° ${signNames[p.sign]||p.sign} · дом ${p.house}${p.retrograde?' · R':''}</span></li>`).join('');content.innerHTML=`<div class="result-copy natal-result"><div class="eyebrow">НАТАЛЬНАЯ КАРТА · SWISS EPHEMERIS</div><div class="result-wheel"><span>☉</span></div><h2>${zodiac(chart.angles.ascendant)} — Асцендент</h2><div class="result-tags"><span>ASC · ${zodiac(chart.angles.ascendant)}</span><span>MC · ${zodiac(chart.angles.midheaven)}</span><span>${chart.aspects.length} аспектов</span></div><ul class="planet-list">${rows}</ul><p><small>Астрономические положения рассчитаны детерминированно. Астрологическая интерпретация не является научным прогнозом.</small></p><button class="primary-btn" onclick="document.querySelector('#modal').close()">Готово</button></div>`}
$$('[data-flow]').forEach(b=>b.onclick=()=>b.dataset.flow==='natal'?natalForm():openResult(flowCopy[b.dataset.flow]));
$('[data-modal="forecast"]').onclick=()=>openResult({k:'ПРОГНОЗ НА СЕГОДНЯ',n:'Спокойствие — твоя сила',v:'☾',p:'Луна усиливает эмоциональную восприимчивость, поэтому сегодня легко принять тревогу за интуицию. До вечера лучше собирать факты, а после 16:00 — обсуждать важное. В работе день подходит для структурирования и завершения начатого.',tags:['Отношения · 7/10','Работа · 9/10','Энергия · 8/10']});
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
$('#profile-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));localStorage.setItem('orbita-profile',JSON.stringify(d));$('#today-title').textContent=d.name;toast('Профиль сохранён')};
const saved=JSON.parse(localStorage.getItem('orbita-profile')||'null');if(saved){Object.entries(saved).forEach(([k,v])=>{const el=$(`[name="${k}"]`);if(el)el.value=v});$('#today-title').textContent=saved.name||'Алекс'}
$('#dream-form').onsubmit=e=>{e.preventDefault();const t=$('#dream-text').value.trim();if(!t)return;content.innerHTML=`<div class="result-copy"><div class="eyebrow">ИНТЕРПРЕТАЦИЯ СНА</div><div class="result-wheel"><span>☾</span></div><h2>Сон о переходе</h2><div class="result-tags"><span>Перемены</span><span>Скрытые эмоции</span><span>Поиск опоры</span></div><p>Образ сна может говорить о ситуации, в которой ты чувствуешь неопределённость, но уже готов двигаться дальше. Обрати внимание не только на символы, но и на главное чувство после пробуждения — оно часто точнее любого «сонника».</p><p><small>Это символическая интерпретация, а не предсказание или диагноз.</small></p></div>`;modal.showModal();const item=document.createElement('button');item.className='dream-item';item.innerHTML=`<span>✨</span><div><small>Сегодня</small><strong>${t.slice(0,36)}${t.length>36?'…':''}</strong><p>Новая запись · AI-разбор</p></div><b>→</b>`;$('#dream-list').prepend(item);$('#dream-count').textContent='3 записи';$('#dream-text').value=''};
const replies=['Сегодня лучше опираться на факты и не принимать сильную эмоцию за окончательный вывод. Если решение можно отложить до вечера — дай себе эту паузу.','В твоём контексте повторяющийся образ часто связан не с внешним предсказанием, а с внутренней потребностью в безопасности и ясных границах.','Завтра подходит для встречи, если цель — спокойный разговор. Сложные темы лучше формулировать через свои чувства и конкретные просьбы.'];
function ask(text){if(!text.trim())return;const chat=$('#chat');chat.insertAdjacentHTML('beforeend',`<div class="message user">${text.replace(/[<>]/g,'')}</div>`);setTimeout(()=>{chat.insertAdjacentHTML('beforeend',`<div class="message bot">${replies[Math.floor(Math.random()*replies.length)]}</div>`);scrollTo({top:document.body.scrollHeight,behavior:'smooth'})},450)}
$('#chat-form').onsubmit=e=>{e.preventDefault();ask($('#chat-input').value);$('#chat-input').value=''};$$('.suggestions button').forEach(b=>b.onclick=()=>ask(b.textContent));
$('[data-action="notifications"]').onclick=()=>toast('Утренний прогноз включён');
